    68  void *lwan_array_append_heap(struct lwan_array *a, size_t element_size)
    69  {
    70      if (!(a->elements % LWAN_ARRAY_INCREMENT)) {
    71          void *new_base;
    72          size_t new_cap;
    73
    74          if (UNLIKELY(
    75                  add_overflow(a->elements, LWAN_ARRAY_INCREMENT, &new_cap))) {
    76              errno = EOVERFLOW;
    77              return NULL;
    78          }
    79
    80          new_base = reallocarray(a->base, new_cap, element_size);
    81          if (UNLIKELY(!new_base))
    82              return NULL;
    83
    84          a->base = new_base;
    85      }
    86
    87      return ((unsigned char *)a->base) + a->elements++ * element_size;
    88  }
