    90  void *lwan_array_append_inline(struct lwan_array *a,
    91                                 size_t element_size,
    92                                 void *inline_storage)
    93  {
    94      if (!a->base)
    95          a->base = inline_storage;
    96      else if (UNLIKELY(a->base != inline_storage))
    97          return lwan_array_append_heap(a, element_size);
    98
    99      assert(a->elements <= LWAN_ARRAY_INCREMENT);
   100
   101      if (a->elements == LWAN_ARRAY_INCREMENT) {
   102          void *new_base = calloc(2 * LWAN_ARRAY_INCREMENT, element_size);
   103          if (UNLIKELY(!new_base))
   104              return NULL;
   105
   106          a->base = memcpy(new_base, inline_storage,
   107                           LWAN_ARRAY_INCREMENT * element_size);
   108      }
   109
   110      return ((char *)a->base) + a->elements++ * element_size;
   111  }
